// MT2009_PLUS_CATACOMB_YANG_HALF_V1 (helper) (server-patches/drop307; the owner's list of 3 November 2026: "Katakumby:
// drop yang z mobow o polowe, jesli resp mobow jest wiekszy niz standardowy"): a monster below boss rank killed in the
// Devil's Catacomb (map 216 and its instances) drops half its yang while the panel's monster respawn ("Respawny",
// regen.cpp) is above the standard - a faster time (fastMobSpawn216, else fastMobSpawn: 10-99 = every 10-99 % of the
// time) or more monsters a line (m2_mob_count over 100 %). The bosses and the Metins keep theirs; with the standard
// respawn nothing changes.
static bool Mt2009PlusCatacombYangHalf(LPCHARACTER victim)
{
	if (!victim || victim->IsPC() || victim->IsStone() || victim->GetMobRank() >= MOB_RANK_BOSS)
		return false;
	const long mapIndex = victim->GetMapIndex();
	if ((mapIndex >= 10000 ? mapIndex / 10000 : mapIndex) != 216)
		return false;
	quest::CQuestManager& q = quest::CQuestManager::instance();
	int delay = MINMAX(0, q.GetEventFlag("fastMobSpawn216"), 100);
	if (delay == 0)
		delay = MINMAX(0, q.GetEventFlag("fastMobSpawn"), 100);
	return (delay > 0 && delay < 100) || q.GetEventFlag("m2_mob_count") > 100;
}

